// Validate that sheet has data and pass form context forward
const rows    = $input.all();
const form    = $('1. Form - User Requests Sheet Export').first().json;

const userEmail  = (form['Your Email Address']         || '').trim();
const sheetId    = (form['Google Sheet ID']            || '').trim();
const tabName    = (form['Sheet Tab Name']             || '').trim();
const format     = (form['Export Format']              || 'Excel (.xlsx)').trim();
const rawName    = (form['File Name (without extension)'] || '').trim();
const fileName   = rawName !== '' ? rawName : 'Export';

// Validate email
if (!userEmail || !userEmail.includes('@')) {
  throw new Error('Valid email address is required.');
}

// Validate sheet ID
if (!sheetId) {
  throw new Error('Google Sheet ID is required.');
}

// Check that sheet returned data
if (!rows || rows.length === 0 || !rows[0].json || Object.keys(rows[0].json).length === 0) {
  throw new Error(
    'The sheet appears to be empty or the tab name is incorrect. ' +
    'Sheet ID: ' + sheetId + '. Tab: ' + (tabName || 'Sheet1')
  );
}

// Detect format: xlsx or csv
const isXlsx = format.toLowerCase().includes('excel') || format.toLowerCase().includes('xlsx');
const fileExt  = isXlsx ? 'xlsx' : 'csv';
const mimeType = isXlsx ? 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' : 'text/csv';

// Pass all context on each row so Convert File node can access it
return rows.map(function(item) {
  return {
    json: {
      ...item.json,
      _meta: {
        userEmail,
        sheetId,
        fileName,
        fileExt,
        mimeType,
        isXlsx,
        totalRows: rows.length
      }
    }
  };
});
